import numpy as np
F=np.load('feats.npz'); y=F['y']; FOLDS=np.load('folds_rep.npy')
C9=F['C9'].astype(np.float64); M9=F['M9'].astype(np.float64)
def ridge_W(Xtr,Y,lam):
    xm=Xtr.mean(0); Xc=Xtr-xm; ym=Y.mean(0); n,d=Xc.shape
    if d<=n: Wt=np.linalg.solve(Xc.T@Xc+lam*np.eye(d),Xc.T@(Y-ym))
    else: Wt=Xc.T@np.linalg.solve(Xc@Xc.T+lam*np.eye(n),Y-ym)
    return Wt, ym-xm@Wt
Cs=(C9-C9.mean(0))/C9.std(0); Ms=(M9-M9.mean(0))/M9.std(0)
def pcs(X,k):
    Xc=X-X.mean(0); U,S,Vt=np.linalg.svd(Xc,full_matrices=False); return Xc@Vt[:k].T, Vt[:k]
def cv(X,lams):
    res={l:0 for l in lams}
    for fo in FOLDS:
        for f in range(5):
            tr=fo!=f; te=fo==f; Y=np.eye(8)[y[tr]]-1/8
            for l in lams:
                Wt,bb=ridge_W(X[tr],Y,l); res[l]+=((X[te]@Wt+bb).argmax(1)==y[te]).sum()
    return {l:round(res[l]/len(y)/len(FOLDS),4) for l in lams}
# C9 with bottom-k raw-cov PCs removed
ec,Vc=np.linalg.eigh(np.cov(C9.T))
for k2 in [128,256,384]:
    Mp,_=pcs(Ms,k2)
    Cr=C9-(C9-C9.mean(0))@Vc[:,:k2]@Vc[:,:k2].T   # remove bottom-k2 directions
    Crs=(Cr-Cr.mean(0))/(Cr.std(0)+1e-9)
    print(k2,'[C9full,MPC]',cv(np.concatenate([Cs,Mp],1),[300,1000]),' [C9 minus bottom,MPC]',cv(np.concatenate([Crs,Mp],1),[300,1000]))
